L.push({ no: 33, title: "Spatial Patterns of Agriculture: Von Thünen's Model of Agricultural Land Use", subtopic: 'Agriculture as an Economic Activity of the Primary Sector',
  notions: 'Land use pattern, locational rent, isolated state.',
  focus: 'Principle (locational rent); three main assumptions; conclusions and spatial outcome diagram; some areas where applicable.',
  competence: 'Learners are able to explain Von Thünen\'s model and apply it to real areas.',
  objectives: ['State the principle of locational rent.', 'Give the main assumptions of the model.', 'Draw the spatial outcome and give examples.'],
  recall: ['Farmers sell in town markets.', 'Transport costs money.', 'Some products spoil quickly.'],
  situation: 'Around Garoua, vegetable gardens are close to the town, maize fields are farther away and cattle graze far out in the bush. Rachid asks why farming is organised like this.',
  sitQA: [['What is the problem in the situation?', 'We want to explain the pattern of farming around a town.'], ['What is closest to the town?', 'Vegetable gardens.'], ['What is farthest?', 'Cattle grazing.']],
  justification: 'This lesson helps us to understand why farming changes with distance from the market.',
  action: 'Observe how land use changes around your town.',
  activities: [
    { sec: '1. PRINCIPLE', img: 'rent_curves_big.png', caption: 'Locational rent curves.', q: 'What is locational rent?', a: 'The profit from a piece of land after production and transport costs; it falls with distance from the market.', noProj: 'explain with an example.' },
    { sec: '2. ASSUMPTIONS', img: 'vonthunen_big.png', caption: "Von Thünen's model.", q: 'Give three assumptions of the model.', a: 'An isolated state with one central market, flat land of equal fertility, and transport costs that rise with distance.', noProj: 'list assumptions.' },
    { sec: '3. SPATIAL OUTCOME', img: 'vonthunen_big.png', caption: 'The rings of land use.', q: 'Name the four rings from the centre.', a: 'Market gardening and dairy, forestry, arable crops, livestock ranching.', noProj: 'draw the rings.' },
    { sec: '3. CONCLUSION', img: 'f2t_market.jpg', caption: 'A town market.', q: 'Why are vegetables grown near the town?', a: 'They are perishable and heavy to transport, so they give high rent near the market.', noProj: 'discuss vegetables of Garoua.' },
    { sec: '4. APPLICATION', img: 'farm_distance_big.png', caption: 'Farm intensity and distance.', q: 'Where can the model be applied?', a: 'Around towns in Africa, such as Garoua, and around villages (farm intensity falls with distance).', noProj: 'map farming around Garoua.' },
  ],
  summary: [
    D([['Locational rent:', 'It is the profit from land after production and transport costs are paid.']]),
    { title: '1. Principle and Assumptions', intro: 'Von Thünen (1826) based his model on the following ideas:',
      items: [['Principle:', 'Locational rent falls as the distance from the market increases.'],
        ['Isolated state:', 'There is one central market town and no trade with the outside.'],
        ['Uniform land:', 'The land is flat and equally fertile everywhere.'],
        ['Transport:', 'Transport costs rise with distance and farmers seek maximum profit.']] },
    { title: '2. Conclusions and Spatial Outcome', intro: 'Land use forms rings around the market:',
      items: [['Ring 1:', 'Market gardening and dairy farming near the town.'],
        ['Ring 2:', 'Forestry for firewood and timber.'],
        ['Ring 3:', 'Arable crops such as cereals.'],
        ['Ring 4:', 'Livestock ranching far from the town.']],
      draw: { img: 'vonthunen_big.png', caption: "Von Thünen's rings" } },
    { title: '3. Areas where Applicable', intro: 'The model applies in the following areas:',
      items: [['Examples:', 'Rings of land use can be seen around African towns such as Garoua and around villages.']] },
  ],
  evaluation: [['What is locational rent?', 'Profit from land after production and transport costs.'], ['Name the four rings of Von Thünen\'s model.', 'Market gardening/dairy, forestry, arable, ranching.']],
  remediation: ['Von Thünen\'s model has ______ rings.', 'The first ring is market ______.', 'Rent ______ with distance from the market.'],
  remediationAnswers: '1. four 2. gardening 3. falls',
  homework: 'Draw the land use around your town or village and compare it with Von Thünen\'s rings.',
  hwAnswer: 'Around Garoua: vegetable gardens and dairy near town, then maize and cotton fields, then bush pasture for cattle — similar to Von Thünen, though rivers and roads distort the rings.',
  bilingual: [['Land use', "L'utilisation du sol"], ['Rent', 'La rente'], ['Ring', "L'anneau"], ['Market', 'Le marché'], ['Distance', 'La distance'], ['Model', 'Le modèle']],
});

